import React, { useState } from "react";
import DepartmentCard from "../../components/DepartmentCard";
import ContentItem from "../../components/ContentItem";
import TryDoctor from "../../components/TryDoctor"; // interactive doctor activity
import departmentsData from "../../data/departments.json";

const Learn = () => {
  // ----------------------------
  // Selected department
  // ----------------------------
  const [selectedDept, setSelectedDept] = useState(null);

  // ----------------------------
  // Age group filter: "children" or "teens"
  // ----------------------------
  const [ageGroup, setAgeGroup] = useState("children");

  // ----------------------------
  // Optional: automatically set ageGroup from user DOB
  // ----------------------------
  // const age = calculateAge(userData.dob);
  // setAgeGroup(age < 11 ? "children" : "teens");

  return (
    <main className="p-6 min-h-screen bg-slate-100">
      {/* Page Title */}
      <h2 className="text-3xl font-bold mb-6 text-center">
        Learn About the Hospital 🏥
      </h2>

      {/* ----------------------------
          Age Filter Toggle
          ---------------------------- */}
      <div className="flex justify-center gap-4 mb-8">
        <button
          className={`px-5 py-2 rounded-xl font-semibold transition-colors duration-200 ${
            ageGroup === "children"
              ? "bg-purple-500 text-white shadow-lg"
              : "bg-gray-200 text-gray-700 hover:bg-gray-300"
          }`}
          onClick={() => setAgeGroup("children")}
        >
          Children (4–10)
        </button>
        <button
          className={`px-5 py-2 rounded-xl font-semibold transition-colors duration-200 ${
            ageGroup === "teens"
              ? "bg-purple-500 text-white shadow-lg"
              : "bg-gray-200 text-gray-700 hover:bg-gray-300"
          }`}
          onClick={() => setAgeGroup("teens")}
        >
          Teens (11–18)
        </button>
      </div>

      {/* ----------------------------
          Departments Menu
          ---------------------------- */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 mb-8">
        {departmentsData.map((dept) => (
          <DepartmentCard
            key={dept.id}
            name={dept.name}
            icon={dept.icon}
            onClick={() => setSelectedDept(dept)}
          />
        ))}
      </div>

      {/* ----------------------------
          Selected Department Content
          ---------------------------- */}
      {selectedDept && (
        <div className="mb-10">
          <h3 className="text-2xl font-bold mb-4">{selectedDept.name}</h3>

          {/* Map through department content based on age group */}
          {selectedDept.content[ageGroup].map((item, idx) => (
            <ContentItem key={idx} item={item} />
          ))}
        </div>
      )}

      {/* ----------------------------
          Interactive "Try Being the Doctor"
          ---------------------------- */}
      <div className="mb-10">
        <TryDoctor />
      </div>

      {/* Optional encouragement / footer */}
      <div className="text-center text-gray-600 text-sm mt-8">
        👩‍⚕️ Have fun learning and exploring the hospital!
      </div>
    </main>
  );
};

export default Learn;
